// A LP envia texto puro (sendBeacon). Normaliza tudo para uma linha da planilha.
const out = [];
for (const item of $input.all()) {
  let b = item.json.body ?? item.json;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
  const o = b.origem || {};
  const r = b.respostas || {};
  let tel = String(b.telefone || '').replace(/\D/g, '');
  if (tel && !tel.startsWith('55')) tel = '55' + tel;
  const chaves = Object.keys(r);
  out.push({ json: {
    data: new Date(b.data || Date.now()).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    nome: String(b.nome || '').slice(0, 80),
    telefone: tel,
    resposta1: r[chaves[0]] || '',
    resposta2: r[chaves[1]] || '',
    utm_source: o.utm_source || 'direto',
    utm_medium: o.utm_medium || '',
    utm_campaign: o.utm_campaign || '',
    utm_content: o.utm_content || '',
    utm_term: o.utm_term || '',
    status: 'Novo lead',
    valor: '',
    motivo_perda: '',
    link_whatsapp: tel ? 'https://wa.me/' + tel : ''
  }});
}
return out;
